"""Original acid-base chapter: integrated interpretation and calculations."""
from qbank_authoring import question,ref,finalize
AC=ref('French Expert Panel: Diagnosis and Management of Metabolic Acidosis, 2019','https://link.springer.com/article/10.1186/s13613-019-0563-2')
AL=ref('AJKD Core Curriculum: Metabolic Alkalosis, 2022','https://pmc.ncbi.nlm.nih.gov/articles/PMC10947768/')
BI=ref('BICARICU-2 Randomized Clinical Trial, 2025','https://pmc.ncbi.nlm.nih.gov/articles/PMC12573113/')
SA=ref('EXTRIP: Salicylates Recommendations','https://www.extrip-workgroup.org/salicylates')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Blood gas shows pH 7.25, bicarbonate 12 mmol/L and PaCO2 28 mmHg. Which primary disorder is present?', 'Metabolic acidosis',[
 ('Primary respiratory acidosis','The PaCO2 is low, not the primary cause of acidemia.'),('Primary metabolic alkalosis','Bicarbonate is markedly reduced.'),('Primary respiratory alkalosis as the sole disorder','The patient is acidemic; the low PaCO2 is not the acidifying process.')],
 'Name the primary process before checking compensation', '**Acidemia with reduced bicarbonate identifies a metabolic acidifying process.**',['The low PaCO2 may represent compensation.','A second respiratory process requires comparison with the expected range.'], '**Proceed to gap and compensation assessment.**',['Do not infer a single disorder from pH alone.','Integrate electrolytes, lactate, ketones and clinical context.'],[['pH','Acidemia'],['Bicarbonate','Low'],['Primary process','Metabolic acidosis']],[AC])
q('For metabolic acidosis with bicarbonate 12 mmol/L, what PaCO2 is expected by Winter’s formula?', 'Approximately 26 mmHg, with a range of about 24–28',[
 ('Approximately 12 mmHg','This is much lower than the usual expected compensation.'),('Approximately 40 mmHg','This would be too high for appropriate respiratory compensation.'),('Approximately 55 mmHg','This would indicate an additional respiratory acidifying process.')],
 'A prediction tests for an additional respiratory disorder', '**Expected PaCO2 = 1.5 × bicarbonate + 8, plus or minus 2.**',['For 12 mmol/L, the central estimate is 26 mmHg.','The formula is an empirical guide, not a substitute for clinical assessment.'], '**Compare the measured value with the expected range.**',['A higher value suggests added respiratory acidosis.','A lower value suggests added respiratory alkalosis.'],[['Calculation','1.5 × 12 + 8'],['Expected center','26 mmHg'],['Usual range','24–28 mmHg']],[AC])
q('A patient has bicarbonate 10 mmol/L and PaCO2 40 mmHg with acidemia. Which interpretation is correct?', 'Metabolic acidosis with additional respiratory acidosis',[
 ('Appropriate compensation for metabolic acidosis','Expected PaCO2 is about 23 ± 2, not 40.'),('Metabolic acidosis with additional respiratory alkalosis','The measured PaCO2 is too high, not too low.'),('Pure chronic respiratory alkalosis','The acidemia and high relative PaCO2 do not fit.')],
 'A normal-looking PaCO2 can be inappropriate', '**Compensation must be judged relative to the primary disturbance.**',['A PaCO2 of 40 is not normal for bicarbonate 10.','Fatigue, sedation or lung disease can prevent adequate ventilation.'], '**Treat both the metabolic cause and ventilatory problem.**',['Severe acidemia can worsen if ventilation falls further.','Airway interventions require a plan to preserve necessary minute ventilation.'],[['Expected PaCO2','About 23 mmHg'],['Measured','40 mmHg'],['Conclusion','Additional respiratory acidosis']],[AC],'clinical_scenario')
q('Sodium is 140, chloride 104 and bicarbonate 12 mmol/L. What is the anion gap excluding potassium?', '24 mmol/L',[
 ('12 mmol/L','This is the bicarbonate value, not the calculated gap.'),('36 mmol/L','This omits subtraction of bicarbonate.'),('48 mmol/L','This is not the sodium minus chloride plus bicarbonate calculation.')],
 'The gap estimates unmeasured anions', '**Anion gap = sodium − (chloride + bicarbonate).**',['Here 140 − 116 equals 24.','The local reference range depends on the laboratory method.'], '**Correct interpretation for albumin and baseline.**',['Hypoalbuminemia can conceal a meaningful rise.','A raised gap prompts lactate, ketoacid, kidney-failure and toxin assessment.'],[['Sodium','140'],['Chloride plus bicarbonate','116'],['Gap','24 mmol/L']],[AC])
q('The measured anion gap is 12 mmol/L and albumin is 2 g/dL. Using a normal albumin of 4 and correction factor 2.5, what is the corrected gap?', '17 mmol/L',[
 ('7 mmol/L','The correction is added when albumin is low.'),('12 mmol/L','This leaves the albumin deficit unaccounted for.'),('22 mmol/L','This uses twice the specified correction.')],
 'Low albumin lowers the expected baseline gap', '**Corrected gap = measured gap + 2.5 × (4 − albumin in g/dL).**',['The correction here is 5 mmol/L.','The value is approximate and laboratory context matters.'], '**Do not dismiss acid accumulation because the raw gap is normal.**',['Measure suspected acids directly where possible.','Albumin correction complements rather than replaces the clinical diagnosis.'],[['Measured gap','12'],['Albumin correction','5'],['Corrected gap','17']],[AC])
q('Using baseline gap 12 and bicarbonate 24, a patient has gap 32 and bicarbonate 20 mmol/L. Which additional metabolic process is suggested?', 'Concurrent metabolic alkalosis',[
 ('A large additional normal-gap acidosis','That would produce a bicarbonate fall greater than the gap rise.'),('Pure high-gap acidosis with a proportionate bicarbonate fall','The gap rose by 20 while bicarbonate fell by only 4.'),('Primary respiratory acidosis proven by the gap alone','Respiratory classification requires PaCO2.')],
 'Compare the gap rise with the bicarbonate fall', '**A disproportionate gap rise can reveal an alkalinizing process.**',['Vomiting or diuretic exposure can coexist with ketoacidosis.','Baseline values and timing can modify the relationship.'], '**Use delta analysis as a clue rather than an absolute proof.**',['Check history, volume and chloride.','Complete respiratory assessment separately.'],[['Gap rise','20'],['Bicarbonate fall','4'],['Likely addition','Metabolic alkalosis']],[AC,AL])
q('Using baseline gap 12 and bicarbonate 24, gap is 20 and bicarbonate is 8 mmol/L. What does the delta pattern suggest?', 'High-gap acidosis with an additional normal-gap metabolic acidosis',[
 ('High-gap acidosis plus metabolic alkalosis','The bicarbonate has fallen more than the gap has risen.'),('Pure metabolic alkalosis','Bicarbonate is very low.'),('Pure respiratory alkalosis established by these values','PaCO2 and pH are required, and the gap is elevated.')],
 'A larger bicarbonate deficit suggests a second acidifying process', '**The gap rise is 8 while bicarbonate falls by 16.**',['Diarrhea, tubular disease or chloride-rich fluid can provide the extra normal-gap component.','A changing ketoacidosis treatment phase can alter the pattern.'], '**Identify both mechanisms.**',['Interpret with treatment timing and baseline kidney function.','Do not let a high gap hide a simultaneous bicarbonate-loss problem.'],[['Gap rise','8'],['Bicarbonate fall','16'],['Additional process','Normal-gap acidosis']],[AC])
q('Which mechanism produces a normal-anion-gap metabolic acidosis after large-volume chloride-rich fluid administration?', 'An increase in chloride relative to sodium with a fall in bicarbonate',[
 ('Accumulation of an unmeasured organic anion as the defining process','That would usually increase the gap.'),('Loss of all chloride from the circulation','The chloride burden is increased.'),('Primary carbon dioxide retention','That is a respiratory acidifying mechanism.')],
 'Electroneutrality links chloride and bicarbonate', '**A relative chloride excess can produce hyperchloremic acidosis.**',['This can coexist with lactic or other high-gap disease.','The fluid volume and kidney response affect severity.'], '**Review resuscitation and other bicarbonate-loss mechanisms.**',['Use clinically appropriate fluid selection.','Do not assume all residual acidosis means ongoing tissue hypoxia.'],[['Gap','Usually normal'],['Chloride','Relatively increased'],['Context','Chloride-rich fluid exposure']],[AC])
q('A patient with sepsis has high lactate but no marked fall in pH. Which statement is correct?', 'A concurrent alkalinizing process can mask the acid-base effect of lactate accumulation',[
 ('Normal pH excludes clinically important hyperlactatemia','Mixed processes can normalize pH.'),('Lactate is always unrelated to severity','Context and trajectory can be important.'),('A single lactate proves only tissue hypoxia in every case','Adrenergic stimulation, drugs and impaired clearance can contribute.')],
 'Concentration, mechanism and net pH are separate questions', '**A normal pH does not exclude a serious mixed disorder.**',['Respiratory alkalosis is common in sepsis.','Liver clearance and nonhypoxic production can affect lactate.'], '**Assess perfusion and the broader differential.**',['Follow trends with clinical response.','Treat the cause rather than pursuing a number with indiscriminate fluid.'],[['Lactate','May rise through several mechanisms'],['pH','Net result of all processes'],['Assessment','Perfusion plus context']],[AC],'clinical_scenario')
q('A patient taking an SGLT2 inhibitor has nausea, high-gap acidosis and elevated beta-hydroxybutyrate with glucose 170 mg/dL. Which diagnosis is most concerning?', 'Euglycemic diabetic ketoacidosis',[
 ('DKA is excluded because glucose is below 250 mg/dL','SGLT2-associated DKA can occur without marked hyperglycemia.'),('Pure respiratory acidosis','The high gap and ketonemia identify metabolic acid accumulation.'),('Uncomplicated starvation is proven without further assessment','Diabetes, drug exposure and acidosis warrant urgent DKA evaluation.')],
 'Glucose does not define the full ketoacidosis risk', '**SGLT2-associated glycosuria can blunt hyperglycemia despite ketosis.**',['Illness, fasting and reduced insulin are precipitating factors.','Beta-hydroxybutyrate is more informative than relying on urine ketones alone.'], '**Stop the drug and use a monitored DKA treatment pathway.**',['Insulin, fluids, electrolytes and dextrose may all be needed.','Treat the precipitant and review future therapy.'],[['Acidosis','High gap'],['Ketones','Elevated beta-hydroxybutyrate'],['Glucose','Can be modest']],[AC],'clinical_scenario')
q('Why can a negative or weak urine nitroprusside ketone result underestimate early severe ketoacidosis?', 'The assay does not adequately measure beta-hydroxybutyrate',[
 ('It measures only lactate','Nitroprusside primarily detects acetoacetate and, variably, acetone.'),('It directly measures every ketoacid equally','Beta-hydroxybutyrate is poorly detected.'),('It proves that ketone production has ceased','The result can miss the predominant ketone.')],
 'Know what the assay actually detects', '**Beta-hydroxybutyrate can predominate in DKA.**',['Its conversion back to acetoacetate during recovery can increase urine ketone positivity.','That rise does not necessarily indicate worsening disease.'], '**Use blood beta-hydroxybutyrate and clinical acid-base assessment where available.**',['Avoid monitoring recovery from urine ketones alone.','Interpret every assay with its analytical limits.'],[['Early DKA','Beta-hydroxybutyrate predominance'],['Nitroprusside','Mainly acetoacetate'],['Recovery','Urine result can remain positive']],[AC])
q('Tinnitus, tachypnea and high-gap metabolic acidosis occur with PaCO2 lower than expected by Winter’s formula. Which poisoning is classic?', 'Salicylate poisoning',[
 ('Pure opioid toxicity','This more often causes hypoventilation and respiratory acidosis.'),('Uncomplicated chloride depletion alone','That typically causes metabolic alkalosis.'),('Pure hypercapnic COPD exacerbation','This would not explain the low PaCO2 mixed pattern.')],
 'A mixed respiratory alkalosis and metabolic acidosis is a key clue', '**Salicylates stimulate ventilation and disturb cellular metabolism.**',['A near-normal pH can hide both disorders.','Severity depends on symptoms, chronicity, kidney function and level.'], '**Seek toxicology advice and assess dialysis indications.**',['Alkalinization can be important when appropriate.','Avoid losing compensatory ventilation during airway management.'],[['Respiratory effect','Alkalosis'],['Metabolic effect','High-gap acidosis'],['Clue','Tinnitus and tachypnea']],[SA],'clinical_scenario')
q('A patient with chronic hypercapnia has PaCO2 60 mmHg and bicarbonate about 32 mmol/L. Which explanation best fits?', 'Renal compensation for chronic respiratory acidosis',[
 ('Acute respiratory acidosis must raise bicarbonate by this amount immediately','Immediate buffering produces a smaller increase.'),('A low PaCO2 is the primary abnormality','PaCO2 is elevated.'),('Metabolic acidosis is proven by bicarbonate 32','The bicarbonate is increased rather than decreased.')],
 'Time allows kidney compensation', '**Chronic respiratory acidosis typically raises bicarbonate by about 3.5–4 mmol/L per 10 mmHg PaCO2 increase.**',['Acute buffering raises it by about 1 mmol/L per 10.','These are approximate guides.'], '**Assess for additional metabolic disease when the value departs from expectation.**',['Diuretics and vomiting can add alkalosis.','Sepsis or AKI can add acidosis.'],[['Acute CO2 rise','Small bicarbonate increase'],['Chronic rise','Larger renal increase'],['Clinical use','Detect additional processes']],[AC,AL])
q('PaCO2 falls acutely from 40 to 20 mmHg in a previously well adult. What bicarbonate change is expected from acute respiratory alkalosis alone?', 'A fall of about 4 mmol/L',[
 ('A fall of about 10 mmol/L as the immediate response','That is closer to chronic renal adaptation.'),('A rise of 8 mmol/L','The direction is wrong.'),('No bicarbonate change is possible','Immediate buffering can lower bicarbonate modestly.')],
 'Acute and chronic respiratory compensation differ', '**Acute respiratory alkalosis lowers bicarbonate by about 2 mmol/L per 10 mmHg PaCO2 fall.**',['Chronic adaptation is larger, approximately 4–5 per 10.','Large deviations suggest a second process.'], '**Interpret the timing and clinical cause.**',['Pain, hypoxemia, sepsis and drugs can drive hyperventilation.','A low bicarbonate is not automatically primary metabolic acidosis.'],[['Acute PaCO2 fall','20 mmHg'],['Expected bicarbonate fall','About 4'],['Chronic change','Larger renal adaptation']],[AC])
q('A patient has pH 7.40, PaCO2 20 mmHg and bicarbonate 12 mmol/L. Which interpretation is most appropriate?', 'A mixed disorder is likely despite normal pH',[
 ('The blood gas is normal because pH is normal','Both PaCO2 and bicarbonate are markedly abnormal.'),('Pure metabolic acidosis with expected compensation','Winter’s estimate is about 26, higher than the measured 20.'),('Pure acute respiratory alkalosis','The bicarbonate reduction is too large for acute compensation alone.')],
 'A normal pH can be the crossing point of two disorders', '**Metabolic acidosis and respiratory alkalosis can offset their effects on pH.**',['The expected compensatory range identifies the extra respiratory process.','Sepsis and salicylate toxicity are possible contexts.'], '**Investigate the mechanism of both components.**',['Check the gap, lactate, ketones and exposure history as appropriate.','Avoid labeling this compensated normality without further analysis.'],[['pH','Normal net result'],['Metabolic component','Low bicarbonate'],['Respiratory component','PaCO2 lower than expected']],[AC,SA])
q('A patient with metabolic alkalosis has bicarbonate 36 mmol/L. Which PaCO2 is approximately expected if respiratory compensation is appropriate?', 'About 48 mmHg',[
 ('About 20 mmHg','This would imply an additional respiratory alkalosis.'),('About 80 mmHg','This is too high for usual compensation.'),('Exactly 40 mmHg in all cases','Compensatory hypoventilation generally raises PaCO2.')],
 'Alkalosis produces limited compensatory hypoventilation', '**PaCO2 rises roughly 0.6–0.7 mmHg for each 1 mmol/L bicarbonate rise above 24.**',['For a 12 mmol/L rise, the increase is about 8.','The relation has biological variability.'], '**Check for a second respiratory problem.**',['Hypoxemia limits compensatory hypoventilation.','A substantially different value warrants additional assessment.'],[['Bicarbonate rise','12'],['Expected PaCO2 rise','About 8'],['Expected PaCO2','About 48']],[AL])
q('A recently ventilated patient with chronic CO2 retention develops alkalemia after PaCO2 is rapidly normalized. Which mechanism explains post-hypercapnic alkalosis?', 'Renally retained bicarbonate persists after the respiratory acidosis is abruptly removed',[
 ('Immediate total loss of renal bicarbonate','The kidney has not yet excreted the retained bicarbonate.'),('New organic acid accumulation as the defining mechanism','That would acidify rather than explain alkalemia.'),('PaCO2 must remain high for the alkalosis to exist','The rapid fall in CO2 unmasks it.')],
 'Renal adaptation resolves more slowly than ventilator-driven CO2 changes', '**Chronic hypercapnia increases renal bicarbonate retention.**',['Rapid CO2 correction can leave a metabolic alkalosis.','Chloride and potassium depletion may sustain it.'], '**Review ventilation targets and sustaining factors.**',['Avoid unnecessary abrupt overcorrection of chronic hypercapnia.','Treat volume, chloride and potassium deficits when appropriate.'],[['Before','Chronic respiratory acidosis'],['After rapid ventilation','CO2 falls before bicarbonate'],['Result','Metabolic alkalemia']],[AL],'clinical_scenario')
q('Why can a chemistry-panel low bicarbonate not establish metabolic acidosis by itself?', 'Chronic respiratory alkalosis can also lower bicarbonate through renal adaptation',[
 ('Bicarbonate has no acid-base significance','It is important but must be interpreted with pH and PaCO2.'),('Every low bicarbonate is an assay artifact','True physiological reductions are common.'),('PaCO2 is unnecessary for distinguishing primary processes','It is essential to the integrated interpretation.')],
 'A measured concentration does not identify the primary driver', '**Blood gas analysis separates metabolic acidosis from respiratory alkalosis and mixed disease.**',['The anion gap provides another important clue.','Preanalytical problems can occasionally affect chemistry results.'], '**Interpret pH, PaCO2 and bicarbonate together.**',['Review the clinical time course.','Avoid empiric alkali solely from an isolated chemistry value.'],[['Low bicarbonate','Metabolic or compensatory'],['Blood gas','Defines respiratory relationship'],['Clinical context','Identifies the driver']],[AC])
